483	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
484	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
485	// 保持不变，不留下部分业务变化。
486	func (s *store) save() error {
487		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
488		for i, e := range s.data.Events {
489			s.data.EventsJSON[i] = e.toJSON()
490		}
491		if err := validateData(s.data); err != nil {
492			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
493		}
494		var buf bytes.Buffer
495		enc := json.NewEncoder(&buf)
496		enc.SetIndent("", "  ")
497		if err := enc.Encode(s.data); err != nil {
498			return fmt.Errorf("编码数据失败: %w", err)
499		}
500		if err := os.MkdirAll(s.dir, 0o755); err != nil {
501			return fmt.Errorf("创建数据目录失败: %w", err)
502		}
503		path := filepath.Join(s.dir, dataFileName)
504		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
505		if err != nil {
506			return fmt.Errorf("创建临时数据文件失败: %w", err)
507		}
508		tmpName := tmp.Name()
509		abort := func(err error) error {
510			_ = tmp.Close()
511			_ = os.Remove(tmpName)
512			return err
513		}
514		if _, err := tmp.Write(buf.Bytes()); err != nil {
515			abort(nil)
516			return fmt.Errorf("写入数据失败: %w", err)
517		}
518		if err := tmp.Sync(); err != nil {
519			abort(nil)
520			return fmt.Errorf("写入数据失败: %w", err)
521		}
522		if err := tmp.Close(); err != nil {
523			_ = os.Remove(tmpName)
524			return fmt.Errorf("写入数据失败: %w", err)
525		}
526		if err := os.Rename(tmpName, path); err != nil {
527			_ = os.Remove(tmpName)
528			return fmt.Errorf("保存数据失败: %w", err)
529		}
530		return nil
531	}
