1	package main
2	
3	import (
4		"fmt"
5		"sort"
6		"time"
7	)
8	
9	// 设备维修停机时长统计（只读）。
10	//
11	// 停机区间一律以履历时间为准，而不是工单记录里的重复时间字段：
12	//   - 起点为该工单报修履历的时间；
13	//   - 已关闭/已取消工单的终点为对应关闭/取消履历的时间（取消前的占用同样计入）；
14	//   - 未关闭工单暂算到输入窗口终点，不取运行时刻，也不改变其状态。
15	//
16	// 派工、转派不另起区间。统计只计算工单占用区间与窗口 [start,end) 的交集；
17	// 同一资产不同工单的交集先合并为并集再求时长，重叠部分不重复计算；不同资产
18	// 分别计算。统计成功或失败都不写文件、不初始化目录、不追加履历、不消耗编号，
19	// 也不改变报修请求绑定。
20	
21	// timeWindow 是半开放时间区间 [start, end)。
22	type timeWindow struct {
23		start time.Time
24		end   time.Time
25	}
26	
27	// downtimeResult 为单项资产的统计结果，秒数已向下取整。
28	type downtimeResult struct {
29		AssetID string
30		Name    string
31		Seconds int64
32	}
33	
34	// downtimeAnomaly 描述一张终结工单“结束履历时间早于报修履历时间”的异常。
35	// 该异常只用于统计：它使整次停机查询整体失败，既不使台账失去一致性（因此
36	// 不拒绝原有查询与工单操作），也不自动改写任何时间。
37	type downtimeAnomaly struct {
38		AssetID  string
39		TicketID string
40		Start    time.Time
41		End      time.Time
42	}
43	
44	func (e *downtimeAnomaly) Error() string {
45		return fmt.Sprintf("资产 %s 的工单 %s 终结履历时间（%s）早于报修履历时间（%s），统计失败",
46			e.AssetID, e.TicketID, e.End.Format(time.RFC3339Nano), e.Start.Format(time.RFC3339Nano))
47	}
48	
49	// downtimeForAssets 按给定资产顺序统计窗口 [start,end) 内各资产的停机秒数。
50	// 任一所选资产的任一张终结工单出现结束早于开始（即使该单完全在窗口外），
51	// 整次统计即失败，不返回任何部分结果。调用方负责资产编号的去重与排序。
52	func (s *store) downtimeForAssets(assetIDs []string, start, end time.Time) ([]downtimeResult, error) {
53		results := make([]downtimeResult, 0, len(assetIDs))
54		for _, id := range assetIDs {
55			asset := s.findAsset(id)
56			if asset == nil {
57				return nil, fmt.Errorf("未知资产编号 %q", id)
58			}
59			intervals, err := s.occupancyIntervals(id, start, end)
60			if err != nil {
61				return nil, err
62			}
63			results = append(results, downtimeResult{
64				AssetID: id,
65				Name:    asset.Name,
66				Seconds: unionDurationSeconds(intervals),
67			})
68		}
69		return results, nil
70	}
71	
72	// allAssetIDs 返回按编号字典序排序的全部资产编号。
73	func (s *store) allAssetIDs() []string {
74		ids := make([]string, 0, len(s.data.Assets))
75		for _, a := range s.data.Assets {
76			ids = append(ids, a.ID)
77		}
78		sort.Strings(ids)
79		return ids
80	}
81	
82	// occupancyIntervals 按工单归属及履历序号配对，提取该资产每张工单与窗口
83	// [start,end) 的占用交集。允许编号与履历序号存在间隔、数组乱序、履历时间
84	// 不递增；窗口外与零长度交集不贡献区间。
85	func (s *store) occupancyIntervals(assetID string, start, end time.Time) ([]timeWindow, error) {
86		intervals := make([]timeWindow, 0)
87		for _, t := range s.data.Tickets {
88			if t.AssetID != assetID {
89				continue
90			}
91			// 只按“工单归属 + 履历”配对：扫描该工单的全部履历，取唯一的报修
92			// 履历时间为起点、可能存在的一条关闭/取消履历时间为终点。不读取
93			// 工单记录上的 created_at/closed_at/cancelled_at。
94			var report, terminal *Event
95			for i := range s.data.Events {
96				e := &s.data.Events[i]
97				if e.TicketID != t.ID || e.AssetID != assetID {
98					continue
99				}
100				switch e.Kind {
101				case eventReport:
102					report = e
103				case eventClose, eventCancel:
104					terminal = e
105				}
106			}
107			if report == nil {
108				// 整库一致性检查已保证报修履历恰有一条；走到这里属于内部错误。
109				return nil, fmt.Errorf("数据内部错误：工单 %s 缺少报修履历", t.ID)
110			}
111			occStart := report.Time
112			var occEnd time.Time
113			if terminal != nil {
114				occEnd = terminal.Time
115				// 结束早于开始即整体失败；结束等于开始合法（零长度，后续自然不计）。
116				if occEnd.Before(occStart) {
117					return nil, &downtimeAnomaly{
118						AssetID:  assetID,
119						TicketID: t.ID,
120						Start:    occStart,
121						End:      occEnd,
122					}
123				}
124			} else {
125				// 未关闭工单暂算到输入终点。在终点或之后才报修时，裁剪结果为空，记零。
126				occEnd = end
127			}
128			if iv, ok := clipWindow(occStart, occEnd, start, end); ok {
129				intervals = append(intervals, iv)
130			}
131		}
132		return intervals, nil
133	}
134	
135	// clipWindow 返回占用区间 [occStart,occEnd) 与窗口 [winStart,winEnd) 的交集。
136	// 窗口包含起点、不包含终点；零长度交集以 ok=false 返回。
137	func clipWindow(occStart, occEnd, winStart, winEnd time.Time) (timeWindow, bool) {
138		lo := occStart
139		if winStart.After(lo) {
140			lo = winStart
141		}
142		hi := occEnd
143		if winEnd.Before(hi) {
144			hi = winEnd
145		}
146		if !hi.After(lo) {
147			return timeWindow{}, false
148		}
149		return timeWindow{start: lo, end: hi}, true
150	}
151	
152	// mergeWindows 把可能重叠或相邻的区间合并为并集，按起点排序。时间逆序导致的
153	// 跨工单重叠在此消除，而不是把各工单时长直接相加。
154	func mergeWindows(in []timeWindow) []timeWindow {
155		sorted := make([]timeWindow, len(in))
156		copy(sorted, in)
157		sort.SliceStable(sorted, func(i, j int) bool {
158			if !sorted[i].start.Equal(sorted[j].start) {
159				return sorted[i].start.Before(sorted[j].start)
160			}
161			return sorted[i].end.Before(sorted[j].end)
162		})
163		merged := make([]timeWindow, 0, len(sorted))
164		for _, iv := range sorted {
165			last := len(merged) - 1
166			if last < 0 || iv.start.After(merged[last].end) {
167				merged = append(merged, iv)
168				continue
169			}
170			if iv.end.After(merged[last].end) {
171				merged[last].end = iv.end
172			}
173		}
174		return merged
175	}
176	
177	// unionDurationSeconds 合并区间并集后，对每项资产的合计时长整体向下取整为
178	// 整秒：先合计全部区间的精确时长，最后才取整一次（而不是每段取整后相加，
179	// 否则两个 0.6 秒的分离区间会被错算成 0 秒而非合计 1.2 秒取整为 1 秒）。
180	//
181	// 时长以“整秒 + 秒内纳秒”两部分累加，避免大窗口下纳秒整数溢出
182	// （time.Duration 最多约 292 年，而 RFC3339 时刻跨度可能更大）。
183	func unionDurationSeconds(intervals []timeWindow) int64 {
184		merged := mergeWindows(intervals)
185		var totalSec int64
186		var totalNano int64
187		const nanoPerSec = 1_000_000_000
188		for _, iv := range merged {
189			// Unix() 是向下取整的秒刻度，Nanosecond() 为非负的秒内偏移，
190			// 故 hi-lo 精确等于 (hi.Unix()-lo.Unix()) 秒
191			// 加上 (hi.Nanosecond()-lo.Nanosecond()) 纳秒。
192			dSec := iv.end.Unix() - iv.start.Unix()
193			dNano := int64(iv.end.Nanosecond() - iv.start.Nanosecond())
194			totalSec += dSec
195			totalNano += dNano
196			// 归一化，避免区间很多时秒内部分累积溢出。
197			totalSec += totalNano / nanoPerSec
198			totalNano %= nanoPerSec
199		}
200		// 合计后整体向下取整：秒内部分为负时再减一秒。
201		if totalNano < 0 {
202			totalSec--
203		}
204		return totalSec
205	}
