	}
	if string(dstBefore) == string(readFileBytes(t, dstDir)) {
		t.Fatal("目标台账应已更新")
	}

	// 重载后核对合并结果。
	s, err := openStore(dstDir)
	if err != nil {
		t.Fatalf("重载目标: %v", err)
	}
	if s.data.NextTicketSeq != 5 {
		t.Fatalf("下一工单序号 = %d, 想得到 5", s.data.NextTicketSeq)
	}
